import { execution } from '@dynatrace-sdk/automation-utils';
import { credentialVaultClient } from '@dynatrace-sdk/client-classic-environment-v2';
import { getEnvironmentUrl } from '@dynatrace-sdk/app-environment';
import { queryExecutionClient } from '@dynatrace-sdk/client-query';

const EVENTS_TOKEN_VAULT_ID = 'CREDENTIALS_VAULT-REPLACE_WITH_YOUR_VAULT_ID'; // Replace with your Credential Vault ID
const EVENT_TIMEOUT_MINUTES = 45;
const DASHBOARD_ID = 'REPLACE_WITH_YOUR_DASHBOARD_ID'; // Replace with the UUID of your host-census-signal-coverage dashboard after import
const IGNORE_TAG = 'host-dropout:ignore';

async function resolveToken(id) {
  const normalized = (id || '').trim();
  if (!normalized.startsWith('CREDENTIALS_VAULT-')) {
    throw new Error('EVENTS_TOKEN_VAULT_ID must be a Credential Vault ID');
  }
  const credentials = await credentialVaultClient.getCredentialsDetails({ id: normalized });
  if (!credentials || !credentials.token) {
    throw new Error(`No token found in vault entry ${normalized}`);
  }
  return credentials.token;
}

function classicBaseUrl() {
  const envUrl = String(getEnvironmentUrl() || '').trim();
  if (!envUrl) throw new Error('getEnvironmentUrl() returned empty');
  const env = new URL(envUrl);
  env.host = env.host.replace('.apps.', '.');
  env.pathname = '';
  env.search = '';
  env.hash = '';
  return env.toString().replace(/\/$/, '');
}

function appsBaseUrl() {
  return String(getEnvironmentUrl() || '').trim().replace(/\/$/, '');
}

async function runDql(query) {
  let response = await queryExecutionClient.queryExecute({
    body: { query, requestTimeoutMilliseconds: 60000, fetchTimeoutSeconds: 60 },
  });
  let guard = 0;
  while (response && response.state && response.state !== 'SUCCEEDED' && guard < 60) {
    if (response.state === 'FAILED') {
      throw new Error(`DQL failed: ${JSON.stringify(response.error || response)}`);
    }
    if (!response.requestToken) break;
    await new Promise((r) => setTimeout(r, 1000));
    response = await queryExecutionClient.queryPoll({ requestToken: response.requestToken });
    guard += 1;
  }
  return (response && response.result && response.result.records) || [];
}

async function ingest(baseUrl, token, event) {
  const resp = await fetch(`${baseUrl}/api/v2/events/ingest`, {
    method: 'POST',
    headers: {
      Authorization: `Api-Token ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(event),
  });
  const text = await resp.text();
  if (!resp.ok) throw new Error(`events/ingest HTTP ${resp.status}: ${text}`);
  return text ? JSON.parse(text) : {};
}

function prop(v, fallback = 'unknown') {
  if (v === null || v === undefined || String(v).trim() === '') return fallback;
  return String(v);
}

function hasIgnoreTag(tags) {
  const arr = Array.isArray(tags) ? tags : [];
  return arr.some((t) => String(t).includes(IGNORE_TAG));
}

function ynCount(n) {
  return Number(n || 0) > 0 ? 'Y' : 'N';
}

export default async function () {
  await execution();

  const dropoutQuery = `
timeseries cpu = avg(dt.host.cpu.usage), by:{dt.entity.host}, from:now()-25h, to:now()-1h, interval:1h
| fieldsAdd host = entityName(dt.entity.host), was_active = 1
| fields host_id = dt.entity.host, host, was_active
| append [
  timeseries cpu = avg(dt.host.cpu.usage), by:{dt.entity.host}, from:now()-1h, interval:5m
  | fieldsAdd host = entityName(dt.entity.host), active_1h = 1
  | fields host_id = dt.entity.host, host, active_1h
]
| summarize was_active = takeMax(was_active), active_1h = takeMax(active_1h), host = takeAny(host), by:{host_id}
| filter coalesce(was_active, 0) == 1 and coalesce(active_1h, 0) == 0
| lookup [
  fetch dt.entity.host
  | fields host_id = id, installerVersion, monitoringMode, osType, tags
], sourceField:host_id, lookupField:host_id, fields:{installerVersion, monitoringMode, osType, tags}
| lookup [
  fetch logs, from:now()-25h, to:now()-1h
  | filter isNotNull(dt.entity.host)
  | summarize log_count = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{log_count}
| lookup [
  fetch spans, from:now()-25h, to:now()-1h
  | filter isNotNull(dt.entity.host)
  | summarize span_count = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{span_count}
| fields host_id, host, installerVersion, monitoringMode, osType, tags, log_count, span_count
| sort host asc
`;

  const missing = await runDql(dropoutQuery);
  const missingIds = new Set(missing.map((r) => String(r.host_id || '')).filter(Boolean));

  const recentAlerts = await runDql(`
fetch events, from:now()-6h
| filter event.type == "CUSTOM_ALERT"
| filter startsWith(toString(host_dropout_key), "host-dropout:")
| summarize last_ts = max(timestamp), host_name = takeAny(host_name), by:{host_dropout_key, host_id}
| fields host_dropout_key, host_id, host_name, last_ts
`);

  const baseUrl = classicBaseUrl();
  const appsUrl = appsBaseUrl();
  const token = await resolveToken(EVENTS_TOKEN_VAULT_ID);
  const dashUrl = `${appsUrl}/ui/apps/dynatrace.dashboards/dashboard/${DASHBOARD_ID}`;
  const checkedAt = new Date().toISOString();

  const alerts = [];
  const skipped = [];

  for (const row of missing) {
    const hostId = String(row.host_id || '');
    const host = String(row.host || hostId || 'unknown');
    if (!hostId) continue;
    if (hasIgnoreTag(row.tags)) {
      skipped.push({ host, hostId, reason: IGNORE_TAG });
      continue;
    }

    const key = `host-dropout:${hostId}`;
    const title = `Host dropout: ${host}`;
    const description =
      `${host} (${hostId}) stopped reporting host metrics for at least ~1 hour. ` +
      `It was active earlier in the last ~25h. Check OneAgent service, network path to Dynatrace, and host power/availability. ` +
      `Dashboard: ${dashUrl}`;

    await ingest(baseUrl, token, {
      eventType: 'CUSTOM_ALERT',
      title,
      timeout: EVENT_TIMEOUT_MINUTES,
      entitySelector: `type(HOST),entityId("${hostId}")`,
      properties: {
        source: 'host-dropout-alert-v1',
        host_dropout_key: key,
        host_id: hostId,
        host_name: host,
        silence_minutes: '60+',
        last_seen_hint: 'active between now()-25h and now()-1h; silent in last 1h',
        checked_at: checkedAt,
        installerVersion: prop(row.installerVersion),
        monitoringMode: prop(row.monitoringMode),
        osType: prop(row.osType),
        prior_day_logs: ynCount(row.log_count),
        prior_day_traces: ynCount(row.span_count),
        dashboard_url: dashUrl,
        impact: 'Host monitoring heartbeat missing — host may be down, OneAgent stopped, or network blocked',
      },
    });
    alerts.push({ host, hostId, key });
  }

  const restored = [];
  for (const prev of recentAlerts) {
    const hostId = String(prev.host_id || '').trim();
    if (!hostId) continue;
    if (missingIds.has(hostId)) continue;

    // Confirm host is reporting again in last 1h
    const alive = await runDql(`
timeseries cpu = avg(dt.host.cpu.usage), by:{dt.entity.host}, from:now()-1h, interval:5m
| filter dt.entity.host == "${hostId}"
| summarize samples = count()
`);
    const samples = Number((alive[0] && alive[0].samples) || 0);
    if (samples <= 0) continue;

    const host = String(prev.host_name || hostId);
    const key = `host-dropout:${hostId}`;
    await ingest(baseUrl, token, {
      eventType: 'CUSTOM_INFO',
      title: `Host reporting restored: ${host}`,
      entitySelector: `type(HOST),entityId("${hostId}")`,
      properties: {
        source: 'host-dropout-alert-v1',
        host_dropout_key: key,
        host_id: hostId,
        host_name: host,
        checked_at: checkedAt,
        status: 'restored',
        dashboard_url: dashUrl,
      },
    });
    restored.push({ host, hostId, key });
  }

  return {
    checked_at: checkedAt,
    missing_detected: missing.length,
    alerts_sent: alerts.length,
    skipped,
    restored,
    alerts,
  };
}
